// Helper : calculer le % de mots appris dans un texte
export function calculateComprehension(
    text: string,
    learnedWordIds: Set<number>
): number {
    if (!text || learnedWordIds.size === 0) return 0;

    const words = text.split(/\s+/).filter(w => w.length > 0);
    if (words.length === 0) return 0;

    const learnedArabicSet = new Set(
        QURAN_VOCABULARY
            .filter(w => learnedWordIds.has(w.id))
            .map(w => w.arabic.replace(/[\u064B-\u065F\u0670]/g, '')) // Remove tashkeel for matching
    );

    let matchCount = 0;
    for (const word of words) {
        const clean = word.replace(/[\u064B-\u065F\u0670]/g, '');
        if (learnedArabicSet.has(clean)) {
            matchCount++;
        }
    }

    return Math.round((matchCount / words.length) * 100);
}
